import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createHash} from 'node:crypto';
import {createProofIndexPool} from '/opt/proofofwork-api/server/db/postgres.mjs';
import {decodeCanonicalOpReturnOutput} from '/opt/proofofwork-api/server/canonical-op-return.mjs';
import {parseWorkAmoV5RawPwdnsRecord,workAmoV5DnsSaleAuthorizationsMatch,validateWorkAmoV5SaleTicketSignature} from '/opt/proofofwork-api/server/work-amo-v5.mjs';
import {proofIndexEventParticipantsForItem,proofIndexEventRefsForItem} from '/opt/proofofwork-api/server/proof-index-event-relations.mjs';
const txid='dd498455bb712411341cfde6fab38764281ff6b77076a41012c3bee768475e38', blockHash='00000000000000000000aebc8dc758888998e96e870b9950bcefe53cbb28c9b9';
async function rpc(method,params){const r=await fetch(process.env.BITCOIN_RPC_URL,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Basic '+Buffer.from(process.env.BITCOIN_RPC_USER+':'+process.env.BITCOIN_RPC_PASSWORD).toString('base64')},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params})});const x=await r.json();assert.ok(x.error==null);return x.result;}
const tx=await rpc('getrawtransaction',[txid,true]);assert.equal(tx.blockhash,blockHash);assert.ok(tx.confirmations>0);assert.equal(await rpc('getblockhash',[969136]),blockHash);const block=await rpc('getblock',[blockHash,1]);assert.equal(block.tx[3156],txid);
const decoded=decodeCanonicalOpReturnOutput({scriptpubkey:tx.vout[1].scriptPubKey.hex});assert.equal(decoded.decodeValid,true);const parsed=parseWorkAmoV5RawPwdnsRecord(decoded.text);assert.equal(parsed.kind,'dns-seal');
const signed=parsed.saleAuthorization,unsigned={...signed,anchorSignature:'',anchorTxid:'',signature:''};assert.equal(workAmoV5DnsSaleAuthorizationsMatch(signed,unsigned),true);assert.equal(signed.anchorTxid,parsed.listingId);assert.equal(validateWorkAmoV5SaleTicketSignature({authorization:signed,listingId:parsed.listingId,network:'livenet',unitPriceSats:String(signed.priceSats)}).valid,true);
const inputs=await Promise.all(tx.vin.map(async input=>{const prev=await rpc('getrawtransaction',[input.txid,true]);return prev.vout[input.vout].scriptPubKey.address;}));assert.ok(inputs.includes(signed.sellerAddress));
const response=await fetch('http://127.0.0.1:8081/api/v1/dns-summary?network=livenet&fresh=1');assert.equal(response.status,200);const dns=await response.json();const activity=dns.activity.find(e=>e.txid===txid);assert.ok(activity && activity.valid===true && activity.kind==='dns-seal');assert.equal(activity.rawPayload??activity.payload,decoded.text);
const pool=createProofIndexPool({max:1}),client=await pool.connect();let committed=false;
try{
 await client.query('BEGIN');await client.query("SET LOCAL lock_timeout='5s'");
 const before=(await client.query("SELECT * FROM proof_indexer.events WHERE network='livenet' AND txid=$1 FOR UPDATE",[txid])).rows;assert.equal(before.length,1);const row=before[0];assert.equal(String(row.event_id),'4472609');assert.equal(row.kind,'dns-seal-invalid');assert.equal(row.valid,false);assert.equal(row.raw_payload,decoded.text);assert.equal(row.block_height,969136);assert.equal(row.block_index,3156);assert.equal(row.op_return_vout,1);
 const parent=(await client.query("SELECT raw_tx FROM proof_indexer.transactions WHERE network='livenet' AND txid=$1",[txid])).rows[0];assert.equal(parent.raw_tx.hex,tx.hex);
 const relations={participants:(await client.query('SELECT * FROM proof_indexer.event_participants WHERE event_id=$1',[row.event_id])).rows,refs:(await client.query('SELECT * FROM proof_indexer.event_refs WHERE event_id=$1',[row.event_id])).rows};
 const evidence=JSON.stringify({before:row,relations,canonical:{txid,blockHash,height:969136,index:3156,rawHexSha256:createHash('sha256').update(tx.hex).digest('hex')},approvedScope:'Audit 28 derived DNS event classification only'},null,2);
 const receipt='/data/proofofwork-audit28-dns-repair/before.json';fs.writeFileSync(receipt,evidence,{flag:'wx',mode:0o600});const fd=fs.openSync(receipt,'r');fs.fsyncSync(fd);fs.closeSync(fd);
 const payload={...row.payload,...activity,kind:'dns-seal',valid:true,reason:'',reasonCode:'',parsed,derived:row.payload.derived??[],indexedFrom:row.payload.indexedFrom};
 const key=row.event_key.replace(':dns-seal-invalid:',':dns-seal:');assert.notEqual(key,row.event_key);
 const updated=await client.query("UPDATE proof_indexer.events SET kind='dns-seal',event_key=$1,valid=true,validation_errors='{}'::text[],payload=$2::jsonb,updated_at=now() WHERE event_id=$3 AND kind='dns-seal-invalid' AND valid=false RETURNING event_id,kind,valid",[key,JSON.stringify(payload),row.event_id]);assert.equal(updated.rowCount,1);
 await client.query('DELETE FROM proof_indexer.event_participants WHERE event_id=$1',[row.event_id]);for(const p of proofIndexEventParticipantsForItem(payload,{protocol:'pwdns1',kind:'dns-seal'}))await client.query("INSERT INTO proof_indexer.event_participants(event_id,address,role,powid) VALUES($1,$2,$3,NULLIF($4,'')) ON CONFLICT DO NOTHING",[row.event_id,p.address,p.role,p.powid]);
 await client.query('DELETE FROM proof_indexer.event_refs WHERE event_id=$1',[row.event_id]);for(const r of proofIndexEventRefsForItem(payload))await client.query('INSERT INTO proof_indexer.event_refs(event_id,ref_type,ref_value) VALUES($1,$2,$3) ON CONFLICT DO NOTHING',[row.event_id,r.refType,r.refValue]);
 assert.equal((await client.query("SELECT raw_tx->>'hex' AS hex FROM proof_indexer.transactions WHERE network='livenet' AND txid=$1",[txid])).rows[0].hex,tx.hex);
 await client.query('COMMIT');committed=true;console.log(JSON.stringify({ok:true,txid,eventId:String(row.event_id),beforeKind:row.kind,after:updated.rows[0],evidenceSha256:createHash('sha256').update(evidence).digest('hex'),historicalTransitionsUnchanged:true,canonicalRawTransactionUnchanged:true}));
}catch(error){if(!committed)await client.query('ROLLBACK');throw error;}finally{client.release();await pool.end();}

