import pathlib,os,fcntl,json,shutil,re,subprocess,hashlib
root=pathlib.Path('/var/tmp/proofofwork-deploy');keep=('0e767c69e785-20260929T165314Z','d2c0afaffd9c-20260929T161019Z')
lock=open('/run/proofofwork-ui/deploy.lock','a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
pattern=re.compile(r'proofofwork-ui-(?:source|surfaces)-[0-9a-f]{12,16}-[0-9]{8}T[0-9]{6}Z(?:\.tgz(?:\.sha256)?)?')
plan=[]
for p in sorted(root.iterdir()):
 if not pattern.fullmatch(p.name) or any(k in p.name for k in keep):continue
 assert not p.is_symlink() and not os.path.ismount(p)
 row={'path':str(p),'allocatedBytes':int(subprocess.check_output(['du','-s','-B1',str(p)],text=True).split()[0])}
 if p.is_dir() and 'source-' in p.name and not (p/'.git').exists():continue
 if p.is_dir() and 'source-' in p.name:
  result=subprocess.run(['git','-c','safe.directory='+str(p),'-C',str(p),'rev-parse','HEAD'],capture_output=True,text=True)
  if result.returncode:continue
  row['commit']=result.stdout.strip()
  assert row['commit'].startswith(p.name.split('source-')[1].split('-')[0])
 elif p.is_file():
  h=hashlib.sha256()
  with p.open('rb') as f:
   for b in iter(lambda:f.read(1048576),b''):h.update(b)
  row['sha256']=h.hexdigest()
 plan.append(row)
for proc in pathlib.Path('/proc').glob('[0-9]*'):
 refs=[proc/'cwd',proc/'exe',proc/'root',*list((proc/'fd').glob('*'))]
 for ref in refs:
  try:target=os.readlink(ref)
  except OSError:continue
  assert not any(target==r['path'] or target.startswith(r['path']+'/') for r in plan),target
 try:cmd=(proc/'cmdline').read_bytes().replace(b'\0',b' ').decode(errors='replace')
 except OSError:continue
 assert not any(r['path'] in cmd for r in plan),'process references retired stage'
for base in ['/etc/systemd/system','/etc/caddy','/var/www']:
 for p in pathlib.Path(base).rglob('*'):
  if p.is_symlink():
   assert not any(str(p.resolve())==r['path'] or str(p.resolve()).startswith(r['path']+'/') for r in plan)
  elif p.is_file() and p.stat().st_size<100000 and base!='/var/www':
   text=p.read_text(errors='replace');assert not any(r['path'] in text for r in plan),'config references stage'
receipt=pathlib.Path('/var/backups/proofofwork-ui/cleanup-evidence/audit28-rebuildable-stages-20260929.json');assert not receipt.exists();receipt.write_text(json.dumps({'preservedReleases':keep,'plan':plan},indent=2));os.chmod(receipt,0o600)
with receipt.open('rb') as f:os.fsync(f.fileno())
for row in plan:
 p=pathlib.Path(row['path']);shutil.rmtree(p) if p.is_dir() else p.unlink()
print(json.dumps({'removedPaths':len(plan),'allocatedBytes':sum(r['allocatedBytes'] for r in plan)}));print(subprocess.check_output(['df','-B1','/'],text=True))
